// Regenerates temporal/workflow-bundle.generated.ts — the relayChannel workflow, bundled with
// @temporalio/worker's bundleWorkflowCode, then gzipped + base64. Why pre-bundle instead of bundling
// at runtime: Next emits `new URL("./workflows.ts", import.meta.url)` as a LONE asset, so a runtime
// bundleWorkflowCode of that emitted path can't resolve its `./names` import (it isn't co-located) —
// the keep-warm drain route would 500 on Vercel. Pre-bundling sidesteps that AND removes the heavy
// bundler from the function.
//
// The file also records a SOURCE hash (workflows.ts + names.ts + the @temporalio/worker version).
// The drift test (workflow-bundle.generated.test.ts) re-derives that hash and asserts it matches —
// so a workflow edit without a regenerate fails CI. We hash the SOURCE, not the bundle output,
// because bundleWorkflowCode is only deterministic per machine (CI vs local differ byte-for-byte).
//
//   node scripts/gen-workflow-bundle.mjs           # write the file
//   node scripts/gen-workflow-bundle.mjs --check    # exit 1 if the committed file is stale vs source

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";
import { bundleWorkflowCode } from "@temporalio/worker";
import { workflowBundleSourceSha } from "../temporal/workflow-bundle-source.mjs";

const OUT = fileURLToPath(new URL("../temporal/workflow-bundle.generated.ts", import.meta.url));
const workflowsPath = fileURLToPath(new URL("../temporal/workflows.ts", import.meta.url));
const sourceSha = workflowBundleSourceSha();

const header =
  "// GENERATED by scripts/gen-workflow-bundle.mjs — DO NOT EDIT BY HAND.\n" +
  "// The relayChannel workflow, bundled (bundleWorkflowCode) + gzipped + base64, so the keep-warm\n" +
  "// drain route boots a worker WITHOUT resolving ./names at runtime and WITHOUT the in-function\n" +
  "// bundler. Regenerate after changing temporal/workflows.ts or temporal/names.ts:\n" +
  "//   pnpm --filter @remote-claw/web gen:workflow-bundle\n" +
  "// The drift test (test/broker/workflow-bundle.generated.test.ts) fails if SOURCE_SHA256 is stale.\n";

function render(b64) {
  return (
    `${header}export const WORKFLOW_BUNDLE_SOURCE_SHA256 = "${sourceSha}";\n` +
    `export const WORKFLOW_BUNDLE_GZIP_B64 =\n  "${b64}";\n`
  );
}

function committedSha() {
  try {
    const m = readFileSync(OUT, "utf8").match(/WORKFLOW_BUNDLE_SOURCE_SHA256 = "([0-9a-f]{64})"/);
    return m ? m[1] : "";
  } catch {
    return "";
  }
}

if (process.argv.includes("--check")) {
  if (committedSha() !== sourceSha) {
    console.error(
      "workflow-bundle.generated.ts is STALE vs source — run `pnpm --filter @remote-claw/web gen:workflow-bundle`",
    );
    process.exit(1);
  }
  console.log("workflow-bundle.generated.ts is up to date");
} else {
  const { code } = await bundleWorkflowCode({ workflowsPath });
  const b64 = gzipSync(Buffer.from(code, "utf8"), { level: 9 }).toString("base64");
  writeFileSync(OUT, render(b64));
  console.log(`wrote ${OUT} (sha ${sourceSha.slice(0, 12)}…, ${b64.length} b64 chars)`);
}
